// The official recordings Angel plays in the museum's docked player. Only
// official distribution: the artists' YouTube "Topic" channels (the labels'
// own feed, generated by YouTube from the label's delivery) and the band's
// Vevo channel. Checked on 2026-11-17 with YouTube's oEmbed (author_name)
// and the video's own description ("Provided to YouTube by …"); see
// sankofa-features/research/angel/recordings.yaml. Massive Attack withdrew
// their music from Spotify in September 2025, so nothing here relies on it.

export interface Official {
  youtube: string;
  /** The title as the upload names it. */
  title: string;
  artist: string;
  /** oEmbed author_name. */
  channel: string;
  verified: string;
}

/** The album version, as the band's label delivers it today. */
export const ANGEL: Official = {
  youtube: '66A_3uwuZ_I',
  title: 'Angel (Remastered 2019)',
  artist: 'Massive Attack',
  channel: 'Massive Attack - Topic',
  verified: 'oEmbed author_name "Massive Attack - Topic"; description: "Provided to YouTube by Universal Music Group", ℗ 2019 Virgin Records Limited',
};

/** The official video, directed by Walter Stern (an edit of the song). */
export const VIDEO: Official = {
  youtube: 'hbe3CQamF8k',
  title: 'Angel',
  artist: 'Massive Attack',
  channel: 'MassiveAttackVEVO',
  verified: 'oEmbed author_name "MassiveAttackVEVO"; description: "Directed by Walter Stern"',
};

/**
 * Horace Andy's song, from the compilation "Jah Is the One" (Bunny Lee
 * producing). It is not proven to be the 1973 master, so it is never
 * labelled as the 1973 record.
 */
export const ANDY: Official = {
  youtube: '4hYJngJvS58',
  title: 'You Are My Angel',
  artist: 'Horace Andy',
  channel: 'Horace Andy - Topic',
  verified: 'oEmbed author_name "Horace Andy - Topic"; description: "Provided to YouTube by Gorgon Records", producer Edward O\'Sullivan Lee, composer Horace Keith Hinds',
};

export const OFFICIAL_CHANNELS = /^(.+ - Topic|.+VEVO)$/;
